using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Services;

/// <summary>
/// Server-side implementation that provides shipment data directly (used during prerender/server mode).
/// </summary>
public class ShipmentServerService : IShipmentService
{
    private static readonly List<Shipment> _shipments = GenerateSeedData();

    public Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return Task.FromResult(_shipments.ToList());
    }

    public Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = _shipments.FirstOrDefault(s =>
            s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
        return Task.FromResult(shipment);
    }

    public Task<Shipment?> UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var shipment = _shipments.FirstOrDefault(s => s.Id == id);
        if (shipment != null)
        {
            shipment.Status = status;
        }
        return Task.FromResult(shipment);
    }

    private static List<Shipment> GenerateSeedData() =>
    [
        new Shipment { Id = 1, TrackingNumber = "TRK-001", Origin = "New York, USA", Destination = "London, UK", Status = ShipmentStatus.InTransit, EstimatedDelivery = DateTime.Today.AddDays(3), CustomerEmail = "alice@example.com", Description = "Electronics - 2 boxes", CreatedAt = DateTime.Today.AddDays(-5) },
